const items = $input.all();

const strongAiPatterns = [
  /\bopenai\b/i,
  /\bchatgpt\b/i,
  /\banthropic\b/i,
  /\bclaude\b/i,
  /\bgemini\b/i,
  /\bcopilot\b/i,
  /\bllm\b/i,
