  /\bfoundation model\b/i
];

const weakAiPatterns = [
  /\bai\b/i,
  /\bautomation\b/i,
  /\brobot\b/i,
  /\bneural\b/i
];

const businessPatterns = [
  /\benterprise\b/i,
  /\bbusiness\b/i,
  /\bworkflow\b/i,
  /\bworkflows\b/i,
  /\bproductivity\b/i,
  /\bcompliance\b/i,
  /\bgovernance\b/i,
  /\bregulation\b/i,
  /\bsecurity\b/i,
  /\bsafety\b/i,
  /\bdeveloper\b/i,
  /\bdevelopers\b/i,
