  /\binfrastructure\b/i
];

const excludePatterns = [
  /\bairpods\b/i,
  /\blawn mower\b/i,
  /\bmovie\b/i,
  /\btrailer\b/i,
  /\bgaming\b/i,
  /\bgame\b/i,
