  /\bsports\b/i,
  /\bcamera bag\b/i,
  /\bbackpack\b/i,
  /\bsale\b/i,
  /\bdiscount\b/i
];

const htmlEntities = {
  '&amp;': '&',
  '&quot;': '"',
  '&apos;': "'",
  '&#39;': "'",
  '&nbsp;': ' ',
  '&rsquo;': '’',
  '&lsquo;': '‘',
  '&rdquo;': '”',
  '&ldquo;': '“',
  '&ndash;': '–',
  '&mdash;': '—',
  '&euro;': '€',
  '&yen;': '¥'
};

function decodeHtmlEntities(value) {
  return String(value || '')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)))
    .replace(/&[a-zA-Z0-9#]+;/g, (entity) => htmlEntities[entity] || entity);
}

function cleanText(value) {
  return decodeHtmlEntities(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function slugify(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/https?:\/\//g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function getText(item) {
  return [
    item.json.title,
    item.json.contentSnippet,
    item.json.summary,
    item.json.content,
    item.json.link
  ]
    .filter(Boolean)
    .map(cleanText)
    .join(' ');
}

function hasMatch(patterns, text) {
  return patterns.some((pattern) => pattern.test(text));
}

function isRelevant(item) {
  const text = getText(item);
  const title = cleanText(item.json.title || '');

  const hasStrongAi = hasMatch(strongAiPatterns, text);
  const hasWeakAi = hasMatch(weakAiPatterns, text);
  const hasBusinessContext = hasMatch(businessPatterns, text);
  const hasExcludedTopic = hasMatch(excludePatterns, text);

  if (hasExcludedTopic && !hasStrongAi) {
    return false;
  }

  if (hasStrongAi) {
    return true;
  }

  if (hasWeakAi && hasBusinessContext) {
    return true;
  }

  return false;
}

function getCategory(text) {
  const lower = text.toLowerCase();

  if (
    lower.includes('compliance') ||
    lower.includes('regulation') ||
    lower.includes('governance') ||
    lower.includes('safety') ||
    lower.includes('security') ||
    lower.includes('board') ||
    lower.includes('lawsuit') ||
    lower.includes('trial')
  ) {
    return 'AI Governance';
  }

  if (
    lower.includes('agent') ||
    lower.includes('agentic') ||
    lower.includes('workflow') ||
    lower.includes('automation')
  ) {
    return 'AI Workflows';
  }

  if (
    lower.includes('chip') ||
    lower.includes('chips') ||
    lower.includes('nvidia') ||
    lower.includes('infrastructure') ||
    lower.includes('cloud') ||
    lower.includes('data center') ||
    lower.includes('datacenter')
  ) {
    return 'AI Infrastructure';
  }

  if (
    lower.includes('developer') ||
    lower.includes('api') ||
    lower.includes('tool') ||
    lower.includes('tools') ||
    lower.includes('platform')
  ) {
    return 'AI Tools';
  }

  return 'AI News';
}

function getScore(text) {
  const lower = text.toLowerCase();
  let score = 60;

  if (lower.includes('openai') || lower.includes('chatgpt')) score += 18;
  if (lower.includes('anthropic') || lower.includes('claude')) score += 16;
  if (lower.includes('gemini') || lower.includes('copilot')) score += 14;

  if (
    lower.includes('agent') ||
    lower.includes('agentic') ||
    lower.includes('workflow') ||
    lower.includes('automation')
  ) {
    score += 12;
  }

  if (
    lower.includes('enterprise') ||
    lower.includes('business') ||
    lower.includes('productivity') ||
    lower.includes('company') ||
    lower.includes('companies')
  ) {
    score += 10;
  }

  if (
    lower.includes('compliance') ||
    lower.includes('regulation') ||
    lower.includes('governance') ||
    lower.includes('security') ||
    lower.includes('safety') ||
    lower.includes('board') ||
    lower.includes('lawsuit') ||
    lower.includes('trial')
  ) {
    score += 10;
  }

  if (
    lower.includes('nvidia') ||
    lower.includes('chip') ||
    lower.includes('chips') ||
    lower.includes('infrastructure') ||
    lower.includes('cloud') ||
    lower.includes('data center') ||
    lower.includes('datacenter')
  ) {
    score += 10;
  }

  if (
    lower.includes('funding') ||
    lower.includes('investment') ||
    lower.includes('invest') ||
    lower.includes('launch') ||
    lower.includes('production')
  ) {
    score += 6;
  }

  if (hasMatch(excludePatterns, text)) {
    score -= 18;
  }

  return Math.max(45, Math.min(score, 96));
}

function getRecommendation(score, category) {
  if (score >= 80) {
    return `Für das Trend-Radar priorisieren und kurzfristig prüfen, ob daraus ein konkreter Use Case im Bereich ${category} entsteht.`;
  }

  if (score >= 70) {
    return `Beobachten und mit weiteren Quellen abgleichen, ob sich das Signal im Bereich ${category} verstärkt.`;
  }

  return `Nur als schwaches Signal beobachten und erst priorisieren, wenn weitere relevante Quellen das Thema bestätigen.`;
}

function getBusinessImpact(category, title) {
  if (category === 'AI Governance') {
    return `Dieses Signal ist für AI Governance relevant, weil es auf Veränderungen bei Führung, Kontrolle, Regulierung, Sicherheit oder Vertrauen im KI-Markt hinweist: ${title}`;
  }

  if (category === 'AI Infrastructure') {
    return `Dieses Signal ist für AI Infrastructure relevant, weil es auf neue Investitionen, Chip-Kapazitäten, Rechenleistung oder technische Grundlagen für KI-Systeme hinweist: ${title}`;
  }

  if (category === 'AI Workflows') {
    return `Dieses Signal ist für AI Workflows relevant, weil es auf neue Automatisierungsmöglichkeiten, Agenten-Systeme oder produktivere KI-Prozessketten hinweist: ${title}`;
  }

  if (category === 'AI Tools') {
    return `Dieses Signal ist für AI Tools relevant, weil es auf neue Plattformen, APIs, Entwicklerwerkzeuge oder produktnahe KI-Anwendungen hinweist: ${title}`;
  }

  return `Dieses Signal ist für die KI-Marktbeobachtung relevant, weil es auf mögliche Veränderungen bei KI-Unternehmen, Produkten, Infrastruktur oder Marktstrategien hinweist: ${title}`;
}

const relevantItems = items.filter(isRelevant);

return relevantItems.map((item) => {
  const title = cleanText(item.json.title || 'Unbenannter RSS-Trend');
  const link = item.json.link || '';
  const pubDate = item.json.pubDate || item.json.isoDate || '';
  const text = getText(item);

  const cleanSummary = cleanText(
    item.json.contentSnippet ||
    item.json.summary ||
    item.json.content ||
    title
  );

  const score = getScore(text);
  const category = getCategory(text);
  const status = score >= 80 ? 'Hohe Relevanz' : 'Beobachten';

  return {
    json: {
      id: slugify(link || title),
      name: title,
      category,
      status,
      score,
      businessImpact: getBusinessImpact(category, title),
      summary: cleanSummary.slice(0, 350),
      recommendation: getRecommendation(score, category),
      source: 'The Verge RSS',
      timeframe: pubDate ? 'RSS Import' : 'Unbekannt',
      signalType: 'RSS'
    }
  };
});

const requiredFields = [
  'id',
  'name',
  'category',
  'status',
  'score',
  'businessImpact',
  'summary',
  'recommendation',
  'source',
  'timeframe',
  'signalType'
];

return items.map((item) => {
  const normalized = {};

  for (const field of requiredFields) {
    normalized[field] = item.json[field] ?? '';
  }

  normalized.id = String(normalized.id || '').trim();
  normalized.name = String(normalized.name || '').trim();
  normalized.category = String(normalized.category || 'AI News').trim();
  normalized.status = String(normalized.status || 'Neu').trim();
  normalized.score = Math.max(0, Math.min(100, Number(normalized.score) || 0));

  return { json: normalized };
}).filter((item) => item.json.id && item.json.name);

const candidates = $('Trend-Daten normalisieren').all();
const existingRows = $('Bestehende Trends lesen').all();

const existingIds = new Set(
  existingRows
    .map((item) => String(item.json.id || '').trim())
    .filter(Boolean)
);

const newTrends = candidates.filter((item) => {
  const id = String(item.json.id || '').trim();
  return id && !existingIds.has(id);
});

return newTrends;

const items = $input.all();

const sourceConfigs = {
  'UCXZCJLdBC09xxGZ6gcdrc6A': {
    name: 'YouTube – OpenAI',
    sourceQuality: 100,
    sourceType: 'official_ai_channel',
    signalType: 'YouTube',
    defaultCategory: 'AI News',
    maxItems: 5
  },
  'UCP7jMXSY2xbc3KCAE0MHQ-A': {
    name: 'YouTube – Google DeepMind',
    sourceQuality: 98,
    sourceType: 'official_ai_research_channel',
    signalType: 'YouTube',
    defaultCategory: 'AI Research',
    maxItems: 5
  },
  'UCBHcMCGaiJhv-ESTcWGJPcw': {
    name: 'YouTube – NVIDIA Developer',
    sourceQuality: 92,
    sourceType: 'official_ai_infrastructure_channel',
    signalType: 'YouTube',
    defaultCategory: 'AI Infrastructure',
    maxItems: 5
  }
};

const fallbackSourceConfig = {
  name: 'YouTube – Unknown',
  sourceQuality: 70,
  sourceType: 'youtube_channel',
  signalType: 'YouTube',
  defaultCategory: 'AI News',
  maxItems: 5
};

function asArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function cleanText(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#39;/g, "'")
    .replace(/&#8217;/g, '’')
    .replace(/&#8216;/g, '‘')
    .replace(/&#8220;/g, '“')
    .replace(/&#8221;/g, '”')
    .replace(/&#8230;/g, '…')
    .replace(/\s+/g, ' ')
    .trim();
}

function slugify(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/https?:\/\//g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 90);
}

function getChannelId(feed) {
  return String(
    feed['yt:channelId'] ||
    feed.ytChannelId ||
    feed.channelId ||
    ''
  ).trim();
}

function getSourceConfig(feed) {
  const channelId = getChannelId(feed);

  if (sourceConfigs[channelId]) {
    return sourceConfigs[channelId];
  }

  const feedTitle = cleanText(feed.title || '').toLowerCase();

  if (feedTitle.includes('openai')) {
    return sourceConfigs['UCXZCJLdBC09xxGZ6gcdrc6A'];
  }

  if (feedTitle.includes('google deepmind') || feedTitle.includes('deepmind')) {
    return sourceConfigs['UCP7jMXSY2xbc3KCAE0MHQ-A'];
  }

  if (feedTitle.includes('nvidia')) {
    return sourceConfigs['UCBHcMCGaiJhv-ESTcWGJPcw'];
  }

  return fallbackSourceConfig;
}

function getLink(entry) {
  const links = asArray(entry.link);

  const alternate = links.find((link) => link.rel === 'alternate' && link.href);
  if (alternate?.href) return alternate.href;

  const firstWithHref = links.find((link) => link.href);
  return firstWithHref?.href || '';
}

function getVideoId(entry, link) {
  if (entry['yt:videoId']) return String(entry['yt:videoId']).trim();

  const match = String(link || '').match(/[?&]v=([^&]+)/);
  return match ? match[1] : '';
}

function getMediaGroup(entry) {
  return entry['media:group'] || entry.mediaGroup || {};
}

function getDescription(entry) {
  const mediaGroup = getMediaGroup(entry);

  return cleanText(
    mediaGroup['media:description'] ||
    mediaGroup.description ||
    entry.summary ||
    entry.content ||
    entry.title ||
    ''
  );
}

function getPublishedTimestamp(entry) {
  const dateValue = entry.published || entry.updated || '';
  const timestamp = Date.parse(dateValue);
  return Number.isNaN(timestamp) ? 0 : timestamp;
}

function getCategory(text, sourceConfig) {
  const lower = text.toLowerCase();

  if (
    lower.includes('nvidia') ||
    lower.includes('gpu') ||
    lower.includes('cuda') ||
    lower.includes('dgx') ||
    lower.includes('chip') ||
    lower.includes('infrastructure') ||
    lower.includes('data center') ||
    lower.includes('datacenter')
  ) {
    return 'AI Infrastructure';
  }

  if (
    lower.includes('codex') ||
    lower.includes('developer') ||
    lower.includes('api') ||
    lower.includes('agent') ||
    lower.includes('agents') ||
    lower.includes('automation')
  ) {
    return 'AI Tools';
  }

  if (
    lower.includes('demo') ||
    lower.includes('spark') ||
    lower.includes('sora') ||
    lower.includes('video') ||
    lower.includes('image') ||
    lower.includes('multimodal') ||
    lower.includes('voice') ||
    lower.includes('audio')
  ) {
    return 'AI Product Demo';
  }

  if (
    lower.includes('gemma') ||
    lower.includes('research') ||
    lower.includes('model') ||
    lower.includes('benchmark') ||
    lower.includes('safety') ||
    lower.includes('alignment')
  ) {
    return 'AI Research';
  }

  if (
    lower.includes('enterprise') ||
    lower.includes('business') ||
    lower.includes('workflow') ||
    lower.includes('productivity')
  ) {
    return 'AI Workflows';
  }

  return sourceConfig.defaultCategory;
}

function getScore(text, category, sourceConfig) {
  const lower = text.toLowerCase();
  let score = 76;

  score += Math.round(sourceConfig.sourceQuality / 10);

  if (lower.includes('openai')) score += 8;
  if (lower.includes('deepmind')) score += 8;
  if (lower.includes('google')) score += 5;
  if (lower.includes('nvidia')) score += 8;
  if (lower.includes('gpu') || lower.includes('cuda') || lower.includes('dgx')) score += 8;
  if (lower.includes('chatgpt')) score += 8;
  if (lower.includes('codex')) score += 10;
  if (lower.includes('gemma')) score += 10;
  if (lower.includes('agent') || lower.includes('agents')) score += 8;
  if (lower.includes('api') || lower.includes('developer')) score += 6;
  if (lower.includes('sora') || lower.includes('video')) score += 6;
  if (lower.includes('research') || lower.includes('model')) score += 5;
  if (lower.includes('enterprise') || lower.includes('business')) score += 5;

  if (category === 'AI Infrastructure') score += 5;
  if (category === 'AI Tools') score += 4;
  if (category === 'AI Product Demo') score += 3;
  if (category === 'AI Research') score += 3;

  return Math.max(60, Math.min(score, 98));
}

function getBusinessImpact(category, title, sourceConfig) {
  if (category === 'AI Infrastructure') {
    return `Dieses YouTube-Signal ist für AI Infrastructure relevant, weil es auf KI-Infrastruktur, GPUs, Developer-Tools, Rechenleistung oder technische Grundlagen für KI-Systeme hinweist: ${title}`;
  }

  if (category === 'AI Tools') {
    return `Dieses YouTube-Signal ist für AI Tools relevant, weil es auf neue Funktionen, Entwicklerwerkzeuge, Agenten oder produktnahe KI-Anwendungen hinweist: ${title}`;
  }

  if (category === 'AI Product Demo') {
    return `Dieses YouTube-Signal ist für AI Product Demo relevant, weil es offizielle Produktfunktionen, Demos oder neue Anwendungsmöglichkeiten sichtbar macht: ${title}`;
  }

  if (category === 'AI Research') {
    return `Dieses YouTube-Signal ist für AI Research relevant, weil es Hinweise auf neue Modelle, Forschungsergebnisse, Sicherheitsfragen oder technische Fortschritte liefert: ${title}`;
  }

  if (category === 'AI Workflows') {
    return `Dieses YouTube-Signal ist für AI Workflows relevant, weil es auf neue Automatisierungs- oder Produktivitätsmöglichkeiten mit KI hinweist: ${title}`;
  }

  return `Dieses YouTube-Signal ist für die KI-Marktbeobachtung relevant, weil es von ${sourceConfig.name} stammt und auf neue Entwicklungen im KI-Ökosystem hinweist: ${title}`;
}

function getRecommendation(score, category) {
  if (score >= 85) {
    return `Für das Trend-Radar priorisieren und prüfen, ob daraus ein konkreter Use Case im Bereich ${category} entsteht.`;
  }

  if (score >= 75) {
    return `Beobachten und mit weiteren Quellen abgleichen, ob sich das YouTube-Signal im Bereich ${category} verstärkt.`;
  }

  return `Nur als schwaches YouTube-Signal beobachten und erst priorisieren, wenn weitere Quellen das Thema bestätigen.`;
}

const output = [];

for (const item of items) {
  const feed = item.json.feed || {};
  const sourceConfig = getSourceConfig(feed);

  const entries = asArray(feed.entry)
    .sort((a, b) => getPublishedTimestamp(b) - getPublishedTimestamp(a))
    .slice(0, sourceConfig.maxItems);

  for (const entry of entries) {
    const title = cleanText(entry.title || getMediaGroup(entry)['media:title'] || 'Unbenanntes YouTube-Signal');
    const link = getLink(entry);
    const videoId = getVideoId(entry, link);
    const description = getDescription(entry);
    const published = entry.published || entry.updated || '';

    const combinedText = cleanText(`${title} ${description}`);
    const category = getCategory(combinedText, sourceConfig);
    const score = getScore(combinedText, category, sourceConfig);
    const status = score >= 80 ? 'Hohe Relevanz' : 'Beobachten';

    output.push({
      json: {
        id: slugify(videoId || link || title),
        name: title,
        category,
        status,
        score,
        businessImpact: getBusinessImpact(category, title, sourceConfig),
        summary: description.slice(0, 350) || title,
        recommendation: getRecommendation(score, category),
        source: sourceConfig.name,
        timeframe: published ? 'YouTube Upload' : 'Unbekannt',
        signalType: sourceConfig.signalType
      }
    });
  }
}

return output.filter((item) => item.json.id && item.json.name);

